package com.hmdp.ai.infrastructure.persistence;
import com.hmdp.ai.domain.knowledge.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.Timestamp;import java.time.Instant;import java.util.List;
@Repository public class JdbcOutboxRepository implements OutboxRepository {private final JdbcTemplate jdbc;public JdbcOutboxRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public List<OutboxEvent> findPending(int limit){return jdbc.query("select id,tenant_id,workspace_id,aggregate_type,aggregate_id,event_type,payload_json,attempt from ai_outbox_event where status in ('PENDING','FAILED') and available_at<=? and attempt<10 and deleted=0 order by available_at,id limit ?",(rs,row)->new OutboxEvent(rs.getString("id"),rs.getString("tenant_id"),rs.getString("workspace_id"),rs.getString("aggregate_type"),rs.getString("aggregate_id"),rs.getString("event_type"),rs.getString("payload_json"),rs.getInt("attempt")),Timestamp.from(Instant.now()),limit);}public boolean claim(String id){return jdbc.update("update ai_outbox_event set status='PUBLISHING',attempt=attempt+1,updated_by='outbox' where id=? and status in ('PENDING','FAILED') and available_at<=? and deleted=0",id,Timestamp.from(Instant.now()))==1;}public void published(String id){jdbc.update("update ai_outbox_event set status='PUBLISHED',published_at=?,error_message=null,updated_by='outbox' where id=? and status='PUBLISHING'",Timestamp.from(Instant.now()),id);}public void failed(String id,String message){jdbc.update("update ai_outbox_event set status='FAILED',available_at=?,error_message=?,updated_by='outbox' where id=? and status='PUBLISHING'",Timestamp.from(Instant.now().plusSeconds(10)),message==null?null:message.substring(0,Math.min(1000,message.length())),id);}}
